import React, { ReactNode, useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedText from './AnimatedText';

interface AnimatedListProps {
  items: ReactNode[];
  className?: string;
  itemClassName?: string;
  staggerDelay?: number;
  staggerVariation?: number;
  onAnimationComplete?: () => void;
}

/**
 * AnimatedList - A component that animates a list of items with a staggered effect
 * Perfect for category lists, menu items, etc.
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  items,
  className = '',
  itemClassName = '',
  staggerDelay = 0.03,
  staggerVariation = 0.05,
  onAnimationComplete
}) => {
  // Generate random delay values for each item to create organic timing
  const [randomDelays, setRandomDelays] = useState<number[]>([]);

  useEffect(() => {
    // Generate a unique, organic delay for each item
    const delays = items.map((_, index) => {
      // Base delay plus random variation
      const baseDelay = index * staggerDelay;
      const randomFactor = Math.random() * staggerVariation * 2 - staggerVariation;

      // Occasionally add a longer pause (like a human thinking)
      const extraPause = Math.random() > 0.85 ? Math.random() * 0.2 : 0;

      return baseDelay + randomFactor + extraPause;
    });

    setRandomDelays(delays);
  }, [items.length, staggerDelay, staggerVariation]);

  // Container animation variant
  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        delayChildren: 0.05,
        when: 'beforeChildren',
      }
    }
  };

  // Item animation variant
  const item = {
    hidden: { opacity: 0, y: 3 },
    visible: (i: number) => ({ 
      opacity: 1,
      y: 0,
      transition: { 
        duration: 0.15, 
        ease: "easeOut",
        delay: randomDelays[i] || i * staggerDelay
      }
    })
  };

  // Convert each item to handle both string and ReactNode
  const processItem = (content: ReactNode, index: number) => {
    // For string content, wrap in AnimatedText
    if (typeof content === 'string') {
      return <AnimatedText key={index} text={content} />;
    }

    // If it's already a React element, return it
    return content;
  };

  return (
    <motion.ul
      className={className}
      variants={container}
      initial="hidden"
      animate="visible"
      onAnimationComplete={onAnimationComplete}
      style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'flex-start',
        padding: 0,
        margin: 0,
        listStyle: 'none'
      }}
    >
      {items.map((itemContent, index) => (
        <motion.li 
          key={index}
          className={itemClassName}
          custom={index}
          variants={item}
          style={{ width: '100%', justifyContent: 'flex-start' }}
        >
          {processItem(itemContent, index)}
        </motion.li>
      ))}
    </motion.ul>
  );
};

export default AnimatedList;
